rows[31293]={title={{17,1544826467},"어둠 흡수"},description={"^causes the caster to periodically inflict shadow damage to all enemies in a selected area, slowing their movement speed%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","선택한 지역의 모든 적에게 주기적으로 암흑 피해를 입히고 이동 속도를 감소시킵니다. \0311\031 동안 지속됩니다.",{1},{1}},aura={{61,1218313750},"주기적인 피해\010선택한 지역 안에 있는 적의 이동 속도 감소"}}
