rows[33911]={title={{10,372979182},"갑옷 찢기"},description={"^hacks at an enemy's armor, reducing it for each tear armor%. can be applied up to 5 times%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","적의 방어구를 절단하여 갑옷 찢기 효과가 중첩된 만큼 방어도를 감소시킵니다. 최대 5번까지 중첩될 수 있습니다. \0311\031 동안 지속됩니다.",{1},{1}},aura={{14,868982069},"방어도 감소"}}
