rows[33923]={title={{10,745188718},"음파 폭발"},description={"^releases a massive burst of sonic energy that blasts nearby enemies with nature damage, then inflicts additional nature damage every ([%+%-]?%d[%d,.%+%-to –]*) sec for ([%+%-]?%d[%d,.]* %a+)%. while affected by sonic boom, enemy movement speed is reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","막대한 음파 에너지를 내뿜어 주위 적에게 자연 피해를 입히고 \0312\031에 걸쳐 추가로 \0311\031초마다 자연 피해를 입힙니다. 음파 폭발에 걸려 있는 동안에는 이동 속도가 \0313\031%만큼 감소합니다.",{0,1,0},{1,2,3}}}
