rows[34239]={title={{11,1308678712},"생명력 흡수"},description={"^drains ([%+%-]?%d[%d,.%+%-to –]*) health from an enemy over ([%+%-]?%d[%d,.]* %a+)%., transferring it to the caster%.$","\0312\031에 걸쳐 적으로부터 총 \0311\031의 생명력을 흡수하여 시전자에게 이전합니다.",{0,1},{1,2}},aura={"^([%+%-]?%d[%d,.%+%-to –]*) health leeched over ([%+%-]?%d[%d,.]* %a+)%.$","\0312\031에 걸쳐 총 \0311\031의 생명력 착취",{0,1},{1,2}}}
